-- Wächter Migration 200 (nur lesen). Erwartungen: werkzeuge/m200_md5.json. schema = talent_berichte, talent_kampagne_talents, talent_konzepte,
-- talent_mediakits, talent_notizen; funktionen = Fingerabdruck der geänderten und neuen Funktionen; freigabe_spalten = alle Spalten
-- sichtbar_fuer_talent außer talent_deliverables (Tabelle:Typ:Standard:NULL erlaubt; vorher '-').
SELECT (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (WITH t AS (SELECT c.oid, c.relname::text AS tab FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind::text = ANY (ARRAY['r', 'p']) AND c.relname::text = ANY (ARRAY['talent_berichte', 'talent_kampagne_talents', 'talent_konzepte', 'talent_mediakits', 'talent_notizen'])) SELECT 'S|' || t.tab || '|' || a.attname::text || '|' || format_type(a.atttypid, a.atttypmod) || '|' || CASE WHEN a.attnotnull THEN 'NN' ELSE '-' END || '|' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || '|' || a.attidentity::text || a.attgenerated::text AS z FROM t JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid = t.oid AND d.adnum = a.attnum UNION ALL SELECT 'C|' || t.tab || '|' || co.conname::text || '|' || co.contype::text || '|' || pg_get_constraintdef(co.oid) FROM t JOIN pg_constraint co ON co.conrelid = t.oid UNION ALL SELECT 'I|' || t.tab || '|' || ic.relname::text || '|' || pg_get_indexdef(i.indexrelid) FROM t JOIN pg_index i ON i.indrelid = t.oid JOIN pg_class ic ON ic.oid = i.indexrelid UNION ALL SELECT 'T|' || t.tab || '|' || tg.tgname::text || '|' || pg_get_triggerdef(tg.oid) || '|' || tg.tgenabled::text FROM t JOIN pg_trigger tg ON tg.tgrelid = t.oid AND NOT tg.tgisinternal) x) AS schema, (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['talent_bericht_selbst_datei', 'talent_bericht_teilbar', 'talent_chat_kontext', 'talent_freigaben_ui', 'talent_fuer_talent_setzen', 'talent_mediakit_fuer_talent', 'talent_ui_daten', 'talent_ui_kacheln', 'talent_ui_link_oeffnen', 'talent_zugang_ui_aktion', 'talents_mediakit_abgelegt', 'talents_mediakit_selbst_datei', 'talents_mediakit_selbst_ui', 'talents_mediakit_ui_aktion'])) AS funktionen, (SELECT coalesce(string_agg(c.relname::text || ':' || format_type(a.atttypid, a.atttypmod) || ':' || coalesce(pg_get_expr(d.adbin, d.adrelid), '-') || ':' || CASE WHEN a.attnotnull THEN 'NN' ELSE 'null' END, ',' ORDER BY c.relname::text COLLATE "C"), '-') FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind = 'r' AND a.attname::text = 'sichtbar_fuer_talent' COLLATE "C" AND a.attnum > 0 AND NOT a.attisdropped AND c.relname::text <> 'talent_deliverables' COLLATE "C") AS freigabe_spalten;
